mapper.select:
SELECT t.list_id AS listId, t.article_id AS articleId, t.cover_image AS coverImage, t.is_delete AS isDelete FROM ( SELECT cla.list_id, cla.article_id, a.cover_image, a.is_delete, ROW_NUMBER() OVER (PARTITION BY cla.list_id ORDER BY cla.create_time DESC) AS rn FROM collection_list_article cla JOIN article a ON a.id = cla.article_id WHERE cla.list_id IN
#{id}
) t WHERE t.rn <= #{limit}
